begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','submit_report',array['uuid','text','uuid','text'],'Guarded report intake exists');
select ok((select relrowsecurity from pg_class where oid='public.reports'::regclass),'Report RLS enabled');
select ok(not has_function_privilege('anon','public.submit_report(uuid,text,uuid,text)','EXECUTE'),'Anonymous RPC denied');
select ok(not has_function_privilege('service_role','public.submit_report(uuid,text,uuid,text)','EXECUTE'),'Service RPC bypass denied');
select ok(not has_table_privilege('authenticated','public.reports','INSERT,UPDATE,DELETE'),'Direct member writes denied');
select ok(not has_table_privilege('service_role','public.reports','SELECT,INSERT,UPDATE,DELETE'),'Service table bypass denied');
insert into auth.users(id,email) select ('21700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'report-'||n||'@example.invalid' from generate_series(1,7) n;
insert into public.memberships(user_id,role) select ('21700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=4 then 'admin' else 'member' end::public.member_role from generate_series(1,6) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select ('21700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Report pilot','KPAO','licensed' from generate_series(1,5) n;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned test' where user_id='21700000-0000-4000-8000-000000000005';
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility,notes)
select ('21720000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'21700000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','Report C172',2,case when n=2 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility,'Post details not copied into report' from generate_series(1,2) n;
insert into public.flight_recipients(flight_id,user_id) values('21720000-0000-4000-8000-000000000002','21700000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id) values('21730000-0000-4000-8000-000000000001','21720000-0000-4000-8000-000000000002','21700000-0000-4000-8000-000000000002');
update public.flight_requests set status='accepted' where id='21730000-0000-4000-8000-000000000001';
insert into public.conversations(id,flight_request_id,owner_id,requester_id) values('21740000-0000-4000-8000-000000000001','21730000-0000-4000-8000-000000000001','21700000-0000-4000-8000-000000000001','21700000-0000-4000-8000-000000000002');
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('21700000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.report(n integer,kind text default 'pilot',target uuid default '21700000-0000-4000-8000-000000000001',reason text default 'Safety concern') returns jsonb language sql as $$select public.submit_report(('21710000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,kind,target,reason);$$;
set local role authenticated;
select pg_temp.actor(2);
select public.send_conversation_message('21740000-0000-4000-8000-000000000001','21750000-0000-4000-8000-000000000001','Private message never copied canary');
select is(pg_temp.report(1)->>'code','reported','Member can report visible pilot');
select is(pg_temp.report(2,'flight','21720000-0000-4000-8000-000000000001')->>'code','reported','Member can report NETWORK flight');
select is(pg_temp.report(3,'flight','21720000-0000-4000-8000-000000000002')->>'code','reported','Selected requester can report PRIVATE flight');
select is(pg_temp.report(4,'message','21750000-0000-4000-8000-000000000001')->>'code','reported','Participant can report message reference');
select is((select count(*)::integer from public.reports),4,'Reporter reads own reports');
select ok((select bool_and(to_jsonb(r)::text not like '%Private message never copied canary%' and to_jsonb(r)::text not like '%Post details not copied%') from public.reports r),'Target content is not copied into reports');
select is(pg_temp.report(1)->>'code','already_reported','Exact retry confirms original record');
select is(pg_temp.report(1,reason=>'Changed')->>'code','report_conflict','Changed reason cannot overwrite');
select is(pg_temp.report(1,'flight','21720000-0000-4000-8000-000000000001')->>'code','report_conflict','Changed target cannot reuse identity');
select is((select count(*)::integer from public.reports),4,'Retries do not duplicate');
select throws_ok($$select pg_temp.report(10,reason=>' ')$$,'22023',null,'Blank reason denied');
select throws_ok($$select pg_temp.report(10,reason=>repeat('x',2001))$$,'22023',null,'Oversized reason denied');
select throws_ok($$select pg_temp.report(10,'conversation')$$,'22023',null,'Unsupported target rejected');
select is(pg_temp.report(10,'pilot','21700000-0000-4000-8000-000000000005')->>'code','target_unavailable','Disabled profile target denied');
select is(pg_temp.report(10,'pilot','21700000-0000-4000-8000-000000000006')->>'code','target_unavailable','Missing profile target denied');
select is(pg_temp.report(10,'message',gen_random_uuid())->>'code','target_unavailable','Unknown message denied');
select pg_temp.actor(3);
select is((select count(*)::integer from public.reports),0,'Unrelated member cannot read reports');
select is(pg_temp.report(1)->>'code','report_conflict','Foreign retry identity cannot reveal or replace report');
select is(pg_temp.report(10,'flight','21720000-0000-4000-8000-000000000002')->>'code','target_unavailable','Unselected PRIVATE target denied');
select is(pg_temp.report(10,'message','21750000-0000-4000-8000-000000000001')->>'code','target_unavailable','Unrelated message target denied');
select pg_temp.actor(4);
select is((select count(*)::integer from public.reports),4,'Active admin reads reports');
select is(pg_temp.report(10,'flight','21720000-0000-4000-8000-000000000002')->>'code','target_unavailable','Admin has no PRIVATE report-target bypass');
select is(pg_temp.report(10,'message','21750000-0000-4000-8000-000000000001')->>'code','target_unavailable','Admin has no private-message report-target bypass');
select is((select count(*)::integer from public.messages),0,'Admin reading report never gains conversation contents');
select throws_ok($$update public.reports set reason='rewrite'$$,'42501',null,'Admin cannot rewrite reports');
select throws_ok($$delete from public.reports$$,'42501',null,'Admin cannot delete reports');
select pg_temp.actor(5);
select throws_ok($$select pg_temp.report(10)$$,'42501',null,'Disabled reporter denied');
select is((select count(*)::integer from public.reports),0,'Disabled reporter reads denied');
select pg_temp.actor(7);
select throws_ok($$select pg_temp.report(10)$$,'42501',null,'Unadmitted reporter denied');
select pg_temp.actor(1);
select is((select status::text from public.flights where id='21720000-0000-4000-8000-000000000002'),'open','Reports never automatically hide/cancel post');
select is((select status::text from public.flight_requests where id='21730000-0000-4000-8000-000000000001'),'accepted','Reports never automatically close request');
select public.change_flight_recipient('21720000-0000-4000-8000-000000000002','21700000-0000-4000-8000-000000000002',false);
select pg_temp.actor(2);
select is(pg_temp.report(3,'flight','21720000-0000-4000-8000-000000000002')->>'code','already_reported','Own committed receipt survives target access loss');
select is(pg_temp.report(10,'flight','21720000-0000-4000-8000-000000000002')->>'code','target_unavailable','New report rechecks current PRIVATE access');
select is(pg_temp.report(11,'message','21750000-0000-4000-8000-000000000001')->>'code','reported','Retained participant may report closed-history message');
select is((select count(*)::integer from public.messages),1,'Message contents remain participant-only retained history');
reset role;
update public.memberships set role='member' where user_id='21700000-0000-4000-8000-000000000004';
set local role authenticated;
select pg_temp.actor(4);
select is((select count(*)::integer from public.reports),0,'Demoted admin loses other reporters records');
reset role;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned test' where user_id='21700000-0000-4000-8000-000000000002';
set local role authenticated;
select pg_temp.actor(2);
select is((select count(*)::integer from public.reports),0,'Retained disabled session loses own report reads');
select throws_ok($$select pg_temp.report(1)$$,'42501',null,'Disabled session cannot confirm old receipt');
reset role;
select * from finish();
rollback;
